description:
Apply the naming rules of lesson 2.02:

```cpp
bool validPipeName(const std::string& name);
bool samePipe(const std::string& a, const std::string& b);
std::string pipeNameFor(const std::string& product, const std::string& purpose, const std::string& user);
```

- **validPipeName**: the name starts with `\\.\pipe\` or `\\SERVER\pipe\` (a server name of letters, digits, `-`, `_` or `.`, not empty), the part after `pipe\` is not empty and contains no `\`, and the whole string is at most 256 characters. The word `pipe` may be in any case.
- **samePipe**: two names refer to the same pipe if they are equal ignoring case.
- **pipeNameFor** builds `\\.\pipe\product-purpose-user` in lower case, replacing every character that is not a letter or digit in each part with `_`.

starter.solution.cpp:
#include <string>

bool validPipeName(const std::string& name) { return false; }
bool samePipe(const std::string& a, const std::string& b) { return a == b; }
std::string pipeNameFor(const std::string& product, const std::string& purpose, const std::string& user) { return ""; }

solution.solution.cpp:
#include <cctype>
#include <string>

static std::string lower(std::string s)
{
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

bool validPipeName(const std::string& name)
{
    if (name.size() > 256 || name.size() < 2 || name[0] != '\\' || name[1] != '\\') return false;
    const std::size_t serverEnd{ name.find('\\', 2) };
    if (serverEnd == std::string::npos || serverEnd == 2) return false;
    const std::string server{ name.substr(2, serverEnd - 2) };
    if (server != ".")
        for (char c : server)
            if (!std::isalnum(static_cast<unsigned char>(c)) && c != '-' && c != '_' && c != '.') return false;
    if (lower(name.substr(serverEnd, 6)) != "\\pipe\\") return false;
    const std::string rest{ name.substr(serverEnd + 6) };
    return !rest.empty() && rest.find('\\') == std::string::npos;
}

bool samePipe(const std::string& a, const std::string& b) { return lower(a) == lower(b); }

static std::string clean(const std::string& part)
{
    std::string out;
    for (char c : part) out += std::isalnum(static_cast<unsigned char>(c)) ? static_cast<char>(std::tolower(static_cast<unsigned char>(c))) : '_';
    return out;
}

std::string pipeNameFor(const std::string& product, const std::string& purpose, const std::string& user)
{
    return "\\\\.\\pipe\\" + clean(product) + "-" + clean(purpose) + "-" + clean(user);
}

unitTests:
TEST("valid names") {
    CHECK(validPipeName("\\\\.\\pipe\\xenon-indexer"));
    CHECK(validPipeName("\\\\.\\PIPE\\a"));
    CHECK(validPipeName("\\\\build-01\\pipe\\jobs"));
    CHECK(validPipeName("\\\\.\\pipe\\" + std::string(247, 'x')));
}
TEST("invalid names") {
    CHECK(!validPipeName("\\\\.\\pipe\\"));
    CHECK(!validPipeName("\\\\.\\pipe\\a\\b"));
    CHECK(!validPipeName("\\\\.\\pip\\a"));
    CHECK(!validPipeName("\\.\\pipe\\a"));
    CHECK(!validPipeName("\\\\\\pipe\\a"));
    CHECK(!validPipeName("\\\\my server\\pipe\\a"));
    CHECK(!validPipeName("\\\\.\\pipe\\" + std::string(248, 'x')));
    CHECK(!validPipeName("pipe"));
}
TEST("case does not matter") {
    CHECK(samePipe("\\\\.\\pipe\\Xenon", "\\\\.\\PIPE\\xenon"));
    CHECK(!samePipe("\\\\.\\pipe\\a", "\\\\.\\pipe\\b"));
}
TEST("building names") {
    CHECK_EQ(pipeNameFor("Xenon", "indexer", "Sam Smith"), std::string("\\\\.\\pipe\\xenon-indexer-sam_smith"));
    CHECK_EQ(pipeNameFor("My App", "log\\in", "S-1-5-21"), std::string("\\\\.\\pipe\\my_app-log_in-s_1_5_21"));
    CHECK(validPipeName(pipeNameFor("a", "b", "c\\d")));
}

